def render_recheck_html(raw: bytes) -> str:
    """Render the native recheck JSON and embed that exact artifact for download."""
    if not isinstance(raw, bytes):
        raise TypeError("recheck HTML requires the serialized JSON bytes")
    data = json.loads(raw.decode("utf-8"))
    if not isinstance(data, dict) or data.get("schema") != "testpilot.recheck/1":
        raise ValueError("recheck HTML requires the native testpilot.recheck/1 result")
    final = data["final"]
    source = data["source_report"]
    retained = data["retained_tests"]
    observed = final["junit_available"]
    encoded = base64.b64encode(raw).decode("ascii")
    sections = [
        '<!doctype html><html lang="en"><head><meta charset="utf-8">',
        '<meta name="viewport" content="width=device-width, initial-scale=1">',
        '<title>TestPilot saved-test recheck</title>',
        f"<style>{_STYLE}</style></head><body><main>",
        '<header><p class="eyebrow">TestPilot · saved-test recheck</p>',
        '<h1>Inspect the current test result</h1>',
        '<p>The saved tests were checked against the selected checkout. This page reads that completed result; opening it runs no tests or model calls.</p>',
        f'<a class="download" download="recheck.json" href="data:application/json;base64,{encoded}">Download exact recheck JSON</a></header>',
        '<nav aria-label="Report sections"><a href="#result">Current result</a><a href="#cases">Test cases</a><a href="#retained">Retained source</a><a href="#origin">Run identity</a><a href="#output">Recorded output</a></nav>',
        '<section id="result" aria-labelledby="result-title"><h2 id="result-title">Current result</h2>',
        f'<p class="status" id="current-status">{_text(data["status"])}</p>',
        _facts([
            ("Native success", data["ok"]), ("Native run summary", final["summary"]),
            ("Return code", final["returncode"]), ("Timed out", final["timed_out"]),
            ("Duration (seconds)", final["duration_s"]), ("Timeout (seconds)", final["timeout_s"]),
            ("JUnit available", observed), ("New model calls", data["model_calls"]),
        ]),
        '<p class="note">A passing selected suite alone does not qualify the retained tests: the native result also requires a retained case to pass. Historical status is shown separately below.</p>',
    ]
    if observed:
        generated = final["generated"]
        sections.append('<div class="table-scroll"><table><caption>Recorded case counts</caption><thead><tr><th scope="col">Scope</th><th scope="col">Passed</th><th scope="col">Failed</th><th scope="col">Errors</th><th scope="col">Skipped</th><th scope="col">Collected</th></tr></thead><tbody>')
        all_counts = [final[key] for key in ("passed", "failed", "errors", "skipped")]
        sections.append('<tr><th scope="row">Selected suite</th>' + "".join(f"<td>{_value(x)}</td>" for x in [*all_counts, len(final["cases"])]))
        sections.append('</tr><tr><th scope="row">Retained tests</th>' + "".join(
            f"<td>{_value(generated.get(key) if generated is not None else None)}</td>"
            for key in ("passed", "failed", "error", "skipped", "collected")
        ) + "</tr></tbody></table></div>")
    else:
        sections.append('<p class="note" id="unavailable-counts">Case counts are unavailable because this run has no complete JUnit result. Empty recorded case lists and zero count fields are not evidence that no tests ran or that tests passed.</p>')
    sections.extend([
        '</section><section id="cases" aria-labelledby="cases-title"><h2 id="cases-title">Recorded test cases</h2>',
        '<p>Cases remain in recorded order. Native retained-file attribution is shown independently of each case name.</p>',
    ])
    for index, case in enumerate(final["cases"], 1):
        sections.extend([
            f'<details><summary>{index}. {_text(case["outcome"])} · {_text(case["nodeid"])}</summary>',
            _facts([("Recorded node ID", case["nodeid"]), ("Outcome", case["outcome"]),
                    ("Retained-file attribution", case.get("generated_file"))]),
            f'<h3>Recorded diagnostic</h3><pre>{_text(case["message"])}</pre>' if case["message"] else '<p>No diagnostic text was recorded for this case.</p>',
            '</details>',
        ])
    if not final["cases"]:
        sections.append('<p>No individual case records are available in this result.</p>')
    sections.extend([
        '</section><section id="retained" aria-labelledby="retained-title"><h2 id="retained-title">Exact retained test source</h2>',
        '<p>Source below is reading text. Nothing here applies files to a checkout or runs Python. Placement describes the original recheck; the JSON download retains the exact source characters.</p>',
    ])
    for index, item in enumerate(retained, 1):
        sections.extend([
            f'<details><summary>{index}. {_text(item["path"])}</summary>',
            _facts([("Path", item["path"]), ("Placement", item["placement"]),
                    ("UTF-8 bytes", item["bytes"]), ("SHA-256", item["sha256"])]),
            f'<pre>{_text(data["test_files"][item["path"]])}</pre></details>',
        ])
    sections.extend([
        '</section><section id="origin" aria-labelledby="origin-title"><h2 id="origin-title">Run and source identity</h2>',
        _facts([
            ("Schema", data["schema"]), ("Selected checkout path", data["repo"]),
            ("Selected Python", data["python"]), ("Started at", data["started_at"]),
            ("Finished at", data["finished_at"]), ("Source report path", source["path"]),
            ("Source report SHA-256", source["sha256"]),
            ("Historical source status (not this result)", source["recorded_status"]),
            ("This recheck JSON SHA-256", hashlib.sha256(raw).hexdigest()),
            ("Native scope", data["scope"]),
        ]),
        '<p class="note">The source report status remains historical. This recheck adds no model diagnosis, comparison with historical coverage, repository commit identity or guarantee against concurrent checkout changes.</p>',
        '</section><section id="output" aria-labelledby="output-title"><h2 id="output-title">Recorded pytest output tail</h2>',
        '<p>This is the output tail retained by the native result (up to its last 3,000 characters), not a complete log.</p>',
        f'<pre>{_text(final["output"])}</pre>',
        '</section><footer><p class="muted">All report content is local. Reading text visibly escapes HTML-incompatible controls and isolated surrogates; the exact JSON download remains unchanged. Expand source and diagnostics before printing the sections you need.</p></footer>',
        '</main></body></html>\n',
    ])
    return "".join(sections)

"""Execute one retained suite against two immutable local Git revisions."""
from __future__ import annotations

import hashlib
import json
import math
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import subprocess
import sys
import tempfile
from datetime import datetime, timezone
import xml.etree.ElementTree as ET

from .recheck import read_saved_tests
from .sandbox import SandboxResult, run_pytest

SCHEMA = "testpilot.regression/1"
MAX_SOURCE_FILES = 10_000
MAX_SOURCE_FILE_BYTES = 8 * 1024 * 1024
MAX_SOURCE_BYTES = 64 * 1024 * 1024
_OID = re.compile(r"(?:[0-9a-f]{40}|[0-9a-f]{64})\Z")
_GIT_TIMEOUT = 30
_MAX_TREE_OUTPUT = 16 * 1024 * 1024


class RegressionError(ValueError):
    """The requested paired execution could not be admitted or completed."""


def _sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _git(repo: Path, *args: str, limit: int = 4096) -> bytes:
    # Reading original objects must not follow caller GIT_DIR/WORK_TREE,
    # replacements, optional locks, or a promisor's on-demand network fetch.
    env = {k: v for k, v in os.environ.items() if not k.upper().startswith("GIT_")}
    env.update(GIT_CONFIG_NOSYSTEM="1", GIT_CONFIG_GLOBAL=os.devnull,
               GIT_TERMINAL_PROMPT="0")
    try:
        result = subprocess.run(
            ["git", "--no-replace-objects", "--no-lazy-fetch", "--no-optional-locks",
             "-C", str(repo), *args], capture_output=True, env=env, timeout=_GIT_TIMEOUT,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise RegressionError(f"cannot read local Git objects: {exc}") from exc
    if result.returncode:
        detail = result.stderr.decode("utf-8", errors="replace").strip()[-2000:]
        raise RegressionError(f"Git {args[0]} refused: {detail or result.returncode}")
    if len(result.stdout) > limit:
        raise RegressionError(f"Git {args[0]} output exceeds the admitted size limit")
    return result.stdout


def _repository(repo: str | Path) -> Path:
    try:
        project = Path(repo).expanduser().resolve(strict=True)
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        raise RegressionError(f"cannot open repository root: {exc}") from exc
    if not project.is_dir():
        raise RegressionError("repository must be an existing directory")
    if (_git(project, "rev-parse", "--is-inside-work-tree") != b"true\n"
            or _git(project, "rev-parse", "--show-prefix") != b"\n"):
        raise RegressionError("--repo must be the root of a local Git worktree")
    return project


def _revision(repo: Path, ref: str) -> dict:
    if not isinstance(ref, str) or not ref or "\0" in ref:
        raise RegressionError("before and after must be non-empty Git revision strings")
    commit = _git(repo, "rev-parse", "--verify", "--end-of-options", ref + "^{commit}")
    commit = commit.decode("ascii").strip()
    if not _OID.fullmatch(commit):
        raise RegressionError("Git did not return one complete commit identity")
    tree = _git(repo, "rev-parse", "--verify", "--end-of-options", commit + "^{tree}")
    tree = tree.decode("ascii").strip()
    if not _OID.fullmatch(tree):
        raise RegressionError("Git did not return one complete tree identity")
    return {"requested_ref": ref, "commit": commit, "tree": tree}


def _tree_files(repo: Path, tree: str) -> list[dict]:
    raw = _git(repo, "ls-tree", "--full-tree", "-r", "-l", "-z", tree,
               limit=_MAX_TREE_OUTPUT)
    if raw and not raw.endswith(b"\0"):
        raise RegressionError("Git tree listing was incomplete")
    records = raw[:-1].split(b"\0") if raw else []
    if len(records) > MAX_SOURCE_FILES:
        raise RegressionError(f"revision exceeds {MAX_SOURCE_FILES} source files")
    entries = []
    paths = set()
    total = 0
    for record in records:
        try:
            header, path_bytes = record.split(b"\t", 1)
            mode, kind, oid, size_raw = header.split()
            path = path_bytes.decode("utf-8")
            oid = oid.decode("ascii")
            mode = mode.decode("ascii")
        except (ValueError, UnicodeError) as exc:
            raise RegressionError("unsupported or malformed Git tree path/record") from exc
        if kind != b"blob" or mode not in {"100644", "100755"}:
            raise RegressionError(f"unsupported Git entry {path!r}: mode {mode}; "
                                  "symlinks and submodules are not materialized")
        parts = path.split("/")
        if (not path or PurePosixPath(path).is_absolute()
                or any(p in {"", ".", ".."} or p.casefold() == ".git" for p in parts)
                or "\\" in path or ":" in path or path in paths or not _OID.fullmatch(oid)):
            raise RegressionError(f"unsupported or unsafe Git path: {path!r}")
        try:
            size = int(size_raw)
        except ValueError as exc:
            raise RegressionError(f"missing Git blob size for {path!r}") from exc
        if size < 0 or size > MAX_SOURCE_FILE_BYTES:
            raise RegressionError(f"source file {path!r} exceeds {MAX_SOURCE_FILE_BYTES} bytes")
        total += size
        if total > MAX_SOURCE_BYTES:
            raise RegressionError(f"revision exceeds {MAX_SOURCE_BYTES} source bytes")
        paths.add(path)
        entries.append({"path": path, "mode": mode, "blob": oid, "bytes": size})
    return sorted(entries, key=lambda entry: entry["path"].encode("utf-8"))


def _materialize(repo: Path, entries: list[dict], destination: Path) -> None:
    destination.mkdir()
    for entry in entries:
        data = _git(repo, "cat-file", "blob", entry["blob"], limit=entry["bytes"])
        algorithm = hashlib.sha1 if len(entry["blob"]) == 40 else hashlib.sha256
        actual = algorithm(b"blob " + str(len(data)).encode("ascii") + b"\0" + data).hexdigest()
        if len(data) != entry["bytes"] or actual != entry["blob"]:
            raise RegressionError(f"Git blob content/identity changed for {entry['path']!r}")
        target = destination.joinpath(*entry["path"].split("/"))
        target.parent.mkdir(parents=True, exist_ok=True)
        with target.open("xb") as stream:
            stream.write(data)
        target.chmod(0o755 if entry["mode"] == "100755" else 0o644)


def _admit_tests(snapshot: Path, files: dict[str, str]) -> None:
    for path, content in files.items():
        target = snapshot / path
        for parent in target.parents:
            if parent == snapshot:
                break
            if parent.exists() and not parent.is_dir():
                raise RegressionError(f"retained test parent conflicts with committed source: {path}")
        if target.exists() and (not target.is_file() or target.read_bytes() != content.encode("utf-8")):
            raise RegressionError(f"retained test differs from committed source: {path}")


def _comparison(before: SandboxResult, after: SandboxResult, files: dict[str, str]) -> tuple[str, dict]:
    result = {"comparable": False, "reason": "", "case_pairs": [], "witnesses": [],
              "unmatched_before": [], "unmatched_after": []}
    maps = []
    for phase in (before, after):
        mapping = {}
        for case in phase.generated_cases:
            identity = (case.generated_file, case.nodeid)
            if identity in mapping:
                result["reason"] = "duplicate_generated_case_identity"
                return "inconclusive", result
            mapping[identity] = case.outcome
        maps.append(mapping)
    old, new = maps

    def identity_record(key):
        return {"generated_file": key[0], "nodeid": key[1]}

    result["unmatched_before"] = [identity_record(k) for k in sorted(old.keys() - new.keys())]
    result["unmatched_after"] = [identity_record(k) for k in sorted(new.keys() - old.keys())]
    result["case_pairs"] = [{**identity_record(k), "before": old[k], "after": new[k]}
                            for k in sorted(old.keys() & new.keys())]
    if any(p.timed_out or not p.junit_available or p.returncode not in (0, 1) or p.errors
           for p in (before, after)):
        result["reason"] = "incomplete_native_run"
    elif any({key[0] for key in mapping} != set(files) for mapping in maps):
        result["reason"] = "missing_generated_file_collection"
    elif old.keys() != new.keys():
        result["reason"] = "generated_case_identity_mismatch"
    elif any(outcome not in {"passed", "failed"} for mapping in maps for outcome in mapping.values()):
        result["reason"] = "skipped_or_unknown_generated_cases"
    else:
        result["comparable"] = True
        if not after.ok or any(outcome != "passed" for outcome in new.values()):
            result["reason"] = "after_did_not_pass"
            return "after_failed", result
        result["witnesses"] = [pair for pair in result["case_pairs"]
                               if pair["before"] == "failed" and pair["after"] == "passed"]
        if result["witnesses"]:
            result["reason"] = "failed_before_passed_after"
            return "verified_regression", result
        result["reason"] = "no_generated_failure_before"
        return "not_regression", result
    return "inconclusive", result


def check_regression(repo: str | Path, report_path: str | Path, *, before: str, after: str,
                     timeout_s: float = 60.0, python: str | None = None) -> dict:
    """Run exact saved tests on two commits, without changing the worktree/index."""
    try:
        valid_timeout = (isinstance(timeout_s, (int, float)) and not isinstance(timeout_s, bool)
                         and math.isfinite(timeout_s) and timeout_s > 0)
    except OverflowError:
        valid_timeout = False
    if not valid_timeout:
        raise RegressionError("timeout must be a finite positive number")
    if python is not None and (not isinstance(python, str) or not python):
        raise RegressionError("python must identify an executable interpreter")
    chosen = shutil.which(os.path.expanduser(python or sys.executable))
    if chosen is None:
        raise RegressionError(f"Python interpreter is unavailable: {python!r}")
    executable = str(Path(chosen).parent.resolve() / Path(chosen).name)
    started = _now()
    project = _repository(repo)
    try:
        saved = read_saved_tests(report_path)
        files = dict(saved.tests)
        phases = [_revision(project, before), _revision(project, after)]
        listings = [_tree_files(project, phase["tree"]) for phase in phases]
        for phase, entries in zip(phases, listings):
            encoded = json.dumps(entries, ensure_ascii=True, separators=(",", ":")).encode("utf-8")
            phase.update(source_files=len(entries), source_bytes=sum(e["bytes"] for e in entries),
                         snapshot_sha256=_sha(encoded))
        with tempfile.TemporaryDirectory(prefix="testpilot-regression-") as temporary:
            snapshots = [Path(temporary) / label for label in ("before", "after")]
            # A bad after tree/test placement must refuse before the before run.
            for entries, snapshot in zip(listings, snapshots):
                _materialize(project, entries, snapshot)
                _admit_tests(snapshot, files)
            native = [run_pytest(snapshot, dict(files), timeout=timeout_s, python=executable,
                                 coverage=False, exact_files=True) for snapshot in snapshots]
        status, comparison = _comparison(native[0], native[1], files)
        for phase, result in zip(phases, native):
            phase["result"] = result.to_dict()
    except (OSError, ValueError, ET.ParseError) as exc:
        if isinstance(exc, RegressionError):
            raise
        raise RegressionError(f"cannot execute retained revision check: {exc}") from exc
    return {
        "schema": SCHEMA, "status": status, "ok": status == "verified_regression",
        "repo": str(project), "python": executable, "started_at": started, "finished_at": _now(),
        "source_report": {"path": saved.path, "sha256": saved.sha256,
                          "recorded_status": saved.source_status},
        "test_files": files,
        "retained_tests": [{"path": path, "bytes": len(content.encode("utf-8")),
                            "sha256": _sha(content.encode("utf-8"))}
                           for path, content in saved.tests],
        "before": phases[0], "after": phases[1], "comparison": comparison, "model_calls": 0,
        "scope": "Two explicit committed trees; exact retained tests; existing local pytest "
                 "sandbox and collection policy; no model, patch, checkout, or dependency install.",
    }


def _destination(repo: Path, value: str | Path) -> Path:
    target = Path(value).expanduser()
    if target.exists() or target.is_symlink():
        raise RegressionError("output must be a new directory; existing paths are not replaced")
    target = target.resolve()
    if target == repo or target.is_relative_to(repo):
        raise RegressionError("output must be outside the checked repository")
    if not target.parent.is_dir():
        raise RegressionError("output parent directory must already exist")
    return target


def render_regression(result: dict) -> str:
    """Readable observation summary; exact native evidence stays in the JSON."""
    lines = ["# TestPilot retained-suite regression check", "", f"Status: **{result['status']}**", "",
             f"Reason: {result['comparison']['reason']}", "", "| Phase | Commit | Native result |",
             "| --- | --- | --- |"]
    for label in ("before", "after"):
        phase = result[label]
        lines.append(f"| {label} | `{phase['commit']}` | {phase['result']['summary']} |")
    lines += ["", f"Matched failure-to-pass witnesses: {len(result['comparison']['witnesses'])}",
              "", "```json", json.dumps(result["comparison"]["witnesses"], indent=2)
              .replace("`", "\\u0060").replace("<", "\\u003c"), "```", "",
              "Source report SHA-256: `" + result["source_report"]["sha256"] + "`", "",
              "Model calls: 0. These are observations on two explicit revisions; they do not "
              "identify which intervening change caused a result.", "",
              "Project tests run within TestPilot's existing local execution boundary. "
              "This command adds no operating-system or network isolation.", ""]
    return "\n".join(lines)


def run_regression_command(args) -> int:
    """CLI boundary: preserve prior destinations and publish only real results."""
    created = []
    target = None
    owns_directory = False
    try:
        project = _repository(args.repo)
        target = _destination(project, args.out)
        result = check_regression(project, args.report, before=args.before, after=args.after,
                                  timeout_s=args.timeout, python=args.python)
        outputs = {"regression.json": json.dumps(result, indent=2, allow_nan=False) + "\n",
                   "regression.md": render_regression(result)}
        target.mkdir()
        owns_directory = True
        for name, text in outputs.items():
            path = target / name
            with path.open("x", encoding="utf-8", newline="\n") as stream:
                created.append(path)
                stream.write(text)
        print(f"{result['status']}: {result['comparison']['reason']}", flush=True)
        print(f"wrote {target / 'regression.json'}, {target / 'regression.md'}", flush=True)
        return 0 if result["ok"] else 1
    except (OSError, ValueError, RuntimeError) as exc:
        # Remove only files reserved by this invocation. Never remove a prior
        # directory or a concurrent writer's entry.
        for path in created:
            try:
                path.unlink()
            except OSError:
                pass
        if owns_directory:
            try:
                target.rmdir()
            except OSError:
                pass
        if isinstance(exc, BrokenPipeError):
            try:
                sys.stdout.close()
            except OSError:
                pass
        try:
            print(f"testpilot: cannot check regression: {exc}", file=sys.stderr)
        except OSError:
            pass
        return 2

"""Run pytest against a throwaway copy of a repo, with a wall-clock timeout.

Isolation is process-level only: a temp copy of the repo, a fresh process
group killed on timeout, and an environment with credential-looking variables
removed. It is NOT a security boundary against hostile code — run TestPilot in
a container/VM for untrusted repos.
"""
from __future__ import annotations

import json
import os
import shutil
import signal
import subprocess
import sys
import tempfile
import time
import xml.etree.ElementTree as ET
from dataclasses import asdict, dataclass, field
from functools import lru_cache
from pathlib import Path, PurePosixPath

IGNORE = shutil.ignore_patterns(".git", "__pycache__", ".pytest_cache", ".venv", "venv",
                                "*.pyc", ".coverage", "node_modules", ".mypy_cache")
_SECRET_MARKERS = ("KEY", "TOKEN", "SECRET", "PASSWORD", "CREDENTIAL")
_OMIT = "*/tests/*,*/test_*.py,*_test.py,*/conftest.py"
_COVERAGE_PROBE_TIMEOUT_S = 5.0


@dataclass
class CaseResult:
    nodeid: str
    outcome: str  # passed | failed | error | skipped
    message: str = ""
    generated_file: str | None = None


@dataclass
class CoverageReport:
    percent_total: float
    files: dict[str, dict[str, list[int]]] = field(default_factory=dict)

    def executed(self, path: str) -> set[int]:
        return set(self.files.get(path, {}).get("executed", []))

    def executable(self, path: str) -> set[int]:
        f = self.files.get(path, {})
        return set(f.get("executed", [])) | set(f.get("missing", []))


@dataclass
class SandboxResult:
    returncode: int | None
    timed_out: bool
    duration_s: float
    timeout_s: float
    output: str
    cases: list[CaseResult] = field(default_factory=list)
    coverage: CoverageReport | None = None
    generated_files: list[str] = field(default_factory=list)
    junit_available: bool = False

    def _count(self, outcome: str) -> int:
        return sum(1 for c in self.cases if c.outcome == outcome)

    @property
    def passed(self) -> int:
        return self._count("passed")

    @property
    def failed(self) -> int:
        return self._count("failed")

    @property
    def errors(self) -> int:
        return self._count("error")

    @property
    def skipped(self) -> int:
        return self._count("skipped")

    @property
    def generated_cases(self) -> list[CaseResult]:
        return [c for c in self.cases if c.generated_file in self.generated_files]

    def generated_counts(self) -> dict[str, int] | None:
        if not self.generated_files:
            return None
        cases = self.generated_cases
        return {"collected": len(cases),
                **{outcome: sum(c.outcome == outcome for c in cases)
                   for outcome in ("passed", "failed", "error", "skipped")}}

    @property
    def ok(self) -> bool:
        return (not self.timed_out and self.returncode == 0 and self.failed == 0
                and self.errors == 0 and self.passed > 0
                and (not self.generated_files
                     or any(c.outcome == "passed" for c in self.generated_cases)))

    def summary(self) -> str:
        if self.timed_out:
            return f"TIMEOUT after {self.timeout_s:g}s"
        text = (f"{self.passed} passed, {self.failed} failed, {self.errors} errors, "
                f"{self.skipped} skipped (rc={self.returncode})")
        generated = self.generated_counts()
        if generated is not None:
            text += (f"; generated: {generated['passed']} passed of "
                     f"{generated['collected']} collected")
        return text

    def failure_report(self, limit: int = 4000) -> str:
        parts = [self.summary()]
        generated = self.generated_counts()
        if generated is not None and generated["passed"] == 0:
            parts.append("No generated test case passed. Existing-suite passes cannot verify "
                         "the generated files. Write runnable tests and check project collection "
                         "rules, deselection and skip conditions.")
        if self.timed_out:
            parts.append("The test run exceeded the time limit and was killed. "
                         "Look for infinite loops, blocking I/O, or very slow tests.")
        for c in self.cases:
            if c.outcome in ("failed", "error"):
                parts.append(f"--- {c.outcome.upper()}: {c.nodeid}\n{c.message.strip()}")
        if not any(c.outcome in ("failed", "error") for c in self.cases):
            parts.append("--- pytest output (tail)\n" + self.output[-2000:])
        text = "\n".join(parts)
        return text if len(text) <= limit else text[: limit - 20] + "\n...[truncated]"

    def to_dict(self) -> dict:
        d = asdict(self)
        d.update(passed=self.passed, failed=self.failed, errors=self.errors,
                 skipped=self.skipped, ok=self.ok, summary=self.summary())
        d["generated"] = self.generated_counts()
        d["output"] = self.output[-3000:]
        return d


@lru_cache(maxsize=None)
def coverage_available(python: str) -> bool:
    """Detect optional coverage without waiting indefinitely before pytest starts."""
    try:
        result = subprocess.run(
            [python, "-c", "import coverage"], stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            timeout=_COVERAGE_PROBE_TIMEOUT_S,
        )
    except subprocess.TimeoutExpired:
        return False
    return result.returncode == 0


def clean_env(root: Path) -> dict[str, str]:
    env = {k: v for k, v in os.environ.items() if not any(m in k.upper() for m in _SECRET_MARKERS)}
    for k in ("PYTEST_ADDOPTS", "PYTEST_PLUGINS", "COVERAGE_PROCESS_START", "COVERAGE_FILE"):
        env.pop(k, None)
    paths = [str(root / "src")] if (root / "src").is_dir() else []
    env.update(PYTHONPATH=os.pathsep.join(paths + [str(root)]), PYTHONDONTWRITEBYTECODE="1", PYTHONHASHSEED="0")
    return env


def _run(cmd: list[str], cwd: Path, env: dict, timeout: float) -> tuple[int | None, str, bool]:
    """Collect output, bounding POSIX timeout and interrupt cleanup."""
    proc = subprocess.Popen(cmd, cwd=cwd, env=env, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT, text=True, errors="replace", start_new_session=True)
    try:
        out, _ = proc.communicate(timeout=timeout)
        return proc.returncode, out, False
    except KeyboardInterrupt:
        if os.name == "posix":
            try:
                try:
                    os.killpg(proc.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                # Reap the leader without draining an escaped helper's pipe.
                proc.wait(timeout=1.0)
            except (OSError, subprocess.TimeoutExpired):
                # Cleanup failure must not replace the caller's cancellation.
                pass
            finally:
                proc.stdout.close()
        raise
    except subprocess.TimeoutExpired:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except (ProcessLookupError, AttributeError, PermissionError):
            proc.kill()
        try:
            # A detached helper may retain stdout after the target group dies.
            # POSIX communicate uses synchronous reads that we can stop and close;
            # preserve the existing Windows reader-thread cleanup behavior.
            out, _ = proc.communicate(timeout=1.0 if os.name == "posix" else None)
        except subprocess.TimeoutExpired as exc:
            # TimeoutExpired.output is bytes even in text mode. Preserve complete
            # diagnostics plus a replacement for a character cut off by the kill.
            out = (exc.output or b"").decode(proc.stdout.encoding, errors="replace")
            out = out.replace("\r\n", "\n").replace("\r", "\n")
            proc.stdout.close()
            proc.poll()  # Reap the killed leader without waiting for escaped helpers.
        return None, out or "", True


def parse_junit(path: Path) -> list[CaseResult]:
    root = ET.parse(path).getroot()
    cases: list[CaseResult] = []
    for tc in root.iter("testcase"):
        cls, name = tc.get("classname", ""), tc.get("name", "")
        nodeid = f"{cls}::{name}" if cls else name
        outcome, msg = "passed", ""
        for tag, label in (("failure", "failed"), ("error", "error"), ("skipped", "skipped")):
            el = tc.find(tag)
            if el is not None:
                outcome = label
                msg = (el.get("message") or "") + ("\n" + el.text if el.text else "")
                break
        generated_file = None
        for prop in tc.findall("./properties/property"):
            if prop.get("name") == "testpilot.generated_file":
                generated_file = prop.get("value")
                break
        cases.append(CaseResult(nodeid, outcome, msg, generated_file))
    return cases


def _parse_coverage(path: Path, work: Path) -> CoverageReport:
    data = json.loads(path.read_text())
    files = {}
    resolved = work.resolve()
    for name, info in data.get("files", {}).items():
        p = Path(name)
        if p.is_absolute():
            try:
                name = p.resolve().relative_to(resolved).as_posix()
            except ValueError:
                continue
        files[PurePosixPath(name).as_posix()] = {"executed": info.get("executed_lines", []),
                                                 "missing": info.get("missing_lines", [])}
    return CoverageReport(float(data.get("totals", {}).get("percent_covered", 0.0)), files)


def _safe_join(root: Path, rel: str) -> Path:
    p = (root / rel).resolve()
    if root.resolve() not in p.parents:
        raise ValueError(f"refusing to write outside sandbox: {rel}")
    return p


def run_pytest(repo: str | Path, extra_files: dict[str, str] | None = None, *, timeout: float = 60.0,
               python: str | None = None, coverage: bool | None = None,
               pytest_args: tuple[str, ...] = (), exact_files: bool = False) -> SandboxResult:
    """Copy repo, add tests, run pytest and collect native results.

    exact_files admits retained UTF-8 bytes: matching copied files are reused,
    different copied files refuse, and new files use binary output. The default
    generation path retains its existing text-write behavior.
    """
    python = python or sys.executable
    use_cov = coverage_available(python) if coverage is None else coverage
    with tempfile.TemporaryDirectory(prefix="testpilot-") as td:
        tdp = Path(td)
        work = tdp / "repo"
        shutil.copytree(repo, work, ignore=IGNORE)
        for rel, content in (extra_files or {}).items():
            dest = _safe_join(work, rel)
            dest.parent.mkdir(parents=True, exist_ok=True)
            if exact_files:
                data = content.encode("utf-8")
                if dest.exists():
                    if not dest.is_file() or dest.stat().st_size != len(data):
                        raise ValueError(f"copied retained test differs: {rel}")
                    with dest.open("rb") as stream:
                        if stream.read(len(data) + 1) != data:
                            raise ValueError(f"copied retained test differs: {rel}")
                else:
                    with dest.open("xb") as stream:
                        stream.write(data)
            else:
                dest.write_text(content, encoding="utf-8")
        junit = tdp / "junit.xml"
        options = ["-q", "-p", "no:cacheprovider", "--rootdir", str(work), "-o", "addopts=",
              "-o", "junit_family=xunit2", f"--junitxml={junit}", *pytest_args]
        generated_files = sorted(extra_files or {})
        pt = ["-m", "pytest", *options]
        if generated_files:
            runner = tdp / "generated_pytest.py"
            manifest = tdp / "generated_files.json"
            shutil.copyfile(Path(__file__).with_name("_pytest_generated.py"), runner)
            manifest.write_text(json.dumps({str(_safe_join(work, rel)): rel for rel in generated_files}),
                                encoding="utf-8")
            pt = [str(runner), str(manifest), *options]
        data_file = tdp / ".coverage"
        if use_cov:
            cmd = [python, "-m", "coverage", "run", f"--data-file={data_file}", f"--source={work}",
                   f"--omit={_OMIT}", *pt]
        else:
            cmd = [python, *pt]
        env = clean_env(work)
        t0 = time.monotonic()
        rc, out, timed_out = _run(cmd, work, env, timeout)
        dur = time.monotonic() - t0
        junit_available = junit.exists() and not timed_out
        cases = parse_junit(junit) if junit_available else []
        cov = None
        if use_cov and not timed_out:
            # Reserve the report destination after pytest so a failed report
            # command cannot reuse a file left by the test run.
            with tempfile.TemporaryDirectory(prefix="coverage-report-", dir=tdp) as report_dir:
                cov_json = Path(report_dir) / "cov.json"
                crc, _, _ = _run([python, "-m", "coverage", "json", f"--data-file={data_file}", "-o", str(cov_json), "-q"],
                                 work, env, 60)
                # Exit 2 can mean a complete report is below configured fail_under.
                cov = _parse_coverage(cov_json, work) if crc in (0, 2) and cov_json.exists() else None
        return SandboxResult(rc, timed_out, round(dur, 3), timeout, out, cases, cov,
                             generated_files, junit_available)

"""Resolve caller-chosen Python functions without inferring dependency impact."""
from __future__ import annotations

import ast
import tokenize
from collections.abc import Sequence
from pathlib import Path

from .diff import (
    ChangedFunction,
    DiffSourceError,
    _iter_functions,
    _source_path,
    functions_touching,
    is_test_path,
    parse_unified_diff,
)

SELECTION_REASON = "Caller selected these targets; no dependency inference was performed."


class TargetSelectionError(ValueError):
    """An explicit target cannot identify one permitted current function."""


def _requested_specs(targets: Sequence[str]) -> list[str]:
    if isinstance(targets, (str, bytes)) or not isinstance(targets, Sequence):
        raise TargetSelectionError("targets must be a nonempty sequence of path.py::qualname strings")
    requested = list(targets)
    if not requested or any(not isinstance(spec, str) for spec in requested):
        raise TargetSelectionError("targets must be a nonempty sequence of path.py::qualname strings")
    return requested


def selection_record(diff_text: str, targets: Sequence[str]) -> dict:
    """Snapshot caller intent; automatic runs omit this record entirely."""
    if not isinstance(diff_text, str):
        raise TargetSelectionError("the supplied diff must be text")
    return {
        "mode": "explicit",
        "requested": _requested_specs(targets),
        "reason": SELECTION_REASON,
        "diff_text": diff_text,
    }


def resolve_targets(repo: str | Path, diff_text: str,
                    targets: Sequence[str]) -> list[ChangedFunction]:
    """Select exactly named current functions, deduplicated in caller order.

    The existing AST discovery excludes nested functions and includes methods
    and module/class control-flow definitions. A repeated qualified name in one
    source file is ambiguous, even when only one branch executes at runtime.
    No source module is imported or executed during selection.
    """
    requested = _requested_specs(targets)
    root = Path(repo).resolve()
    if not root.is_dir():
        raise TargetSelectionError(f"repository is not a directory: {str(repo)!r}")
    try:
        changes = parse_unified_diff(diff_text)
    except (TypeError, ValueError) as exc:
        raise TargetSelectionError(f"cannot parse supplied diff: {exc}") from exc

    # Resolve identities only: unrelated diff sources are never opened. A diff
    # remains context in explicit mode, and cannot add targets to the request.
    added_by_source: dict[Path, set[int]] = {}
    for change in changes:
        if change.is_deleted or not change.path.endswith(".py") or is_test_path(change.path):
            continue
        try:
            source_path = _source_path(root, change.path)
        except DiffSourceError:
            continue
        added_by_source.setdefault(source_path, set()).update(change.added_lines)

    sources: dict[Path, str] = {}
    functions_by_path: dict[str, list[ChangedFunction]] = {}
    selected: list[ChangedFunction] = []
    seen: set[tuple[Path, str, int, int]] = set()
    for spec in requested:
        raw_path, separator, qualname = spec.rpartition("::")
        if (not separator or not raw_path or not qualname
                or any(not part.isidentifier() for part in qualname.split("."))):
            raise TargetSelectionError(f"expected path.py::qualname: {spec!r}")
        path = Path(raw_path).as_posix()
        if not path.endswith(".py") or is_test_path(path):
            raise TargetSelectionError(f"target must be a Python source file outside tests: {spec!r}")
        try:
            source_path = _source_path(root, raw_path)
            resolved_path = source_path.relative_to(root).as_posix()
            if not resolved_path.endswith(".py") or is_test_path(resolved_path):
                raise TargetSelectionError(f"target resolves to a non-Python or test source: {spec!r}")
            if not source_path.is_file():
                raise TargetSelectionError(f"target source does not exist: {spec!r}")
            if source_path not in sources:
                with tokenize.open(source_path) as source_file:
                    sources[source_path] = source_file.read()
            if path not in functions_by_path:
                source = sources[source_path]
                tree = ast.parse(source, filename=path)
                starts = {node.lineno for _, node, _ in _iter_functions(tree.body)}
                functions_by_path[path] = functions_touching(
                    source, path, starts, added_by_source.get(source_path, set()))
        except TargetSelectionError:
            raise
        except (OSError, ValueError, SyntaxError, LookupError) as exc:
            raise TargetSelectionError(f"cannot inspect target {spec!r}: {exc}") from exc

        matches = [function for function in functions_by_path[path] if function.qualname == qualname]
        if not matches:
            raise TargetSelectionError(f"no selectable function matches {spec!r}")
        if len(matches) != 1:
            raise TargetSelectionError(f"ambiguous target matches {len(matches)} definitions: {spec!r}")
        function = matches[0]
        identity = (source_path, function.qualname, function.lineno, function.end_lineno)
        if identity not in seen:
            selected.append(function)
            seen.add(identity)
    return selected

donor.content:
"""Reopen an explicitly selected saved generation report and matching patch.

This consumer preserves the native renderer. It checks the artifact transport
and renderable layout, not the truth of the recorded execution or diagnosis.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import math
import os
from pathlib import Path
import stat
import sys
import tempfile

from .html_report import render_html_report

MAX_REPORT_BYTES = 16 * 1024 * 1024
MAX_PATCH_BYTES = 4 * 1024 * 1024


class SavedReportError(ValueError):
    """A saved artifact pair cannot be reopened as a native review."""


def _read_file(path: Path, limit: int, label: str) -> bytes:
    flags = os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NONBLOCK", 0)
    descriptor = os.open(path, flags)
    try:
        metadata = os.fstat(descriptor)
        if not stat.S_ISREG(metadata.st_mode):
            raise SavedReportError(f"{label} must be a regular file")
        if metadata.st_size > limit:
            raise SavedReportError(f"{label} exceeds {limit} bytes")
        chunks = []
        remaining = limit + 1
        while remaining:
            chunk = os.read(descriptor, min(remaining, 65536))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        data = b"".join(chunks)
        if len(data) > limit:
            raise SavedReportError(f"{label} exceeds {limit} bytes")
        return data
    finally:
        os.close(descriptor)


def _unique_object(pairs: list[tuple[str, object]]) -> dict:
    result = {}
    for key, value in pairs:
        if key in result:
            raise SavedReportError(f"report has duplicate JSON key {key!r}")
        result[key] = value
    return result


def _finite_float(value: str) -> float:
    result = float(value)
    if not math.isfinite(result):
        raise SavedReportError("report contains a non-finite JSON number")
    return result


def _reject_constant(value: str) -> None:
    raise SavedReportError(f"report contains non-finite JSON number {value}")


def _objects(value: object, label: str) -> list[dict]:
    if not isinstance(value, list) or any(not isinstance(item, dict) for item in value):
        raise SavedReportError(f"{label} must be an array of objects")
    return value


def _files(value: object, label: str) -> None:
    if not isinstance(value, dict) or any(not isinstance(text, str) for text in value.values()):
        raise SavedReportError(f"{label} must map file names to text")


def _booleans(record: dict, names: tuple[str, ...], label: str) -> None:
    for name in names:
        if name in record and not isinstance(record[name], bool):
            raise SavedReportError(f"{label}.{name} must be a boolean")


def _run_layout(value: object, label: str) -> None:
    if value is None:
        return
    if not isinstance(value, dict):
        raise SavedReportError(f"{label} must be an object or null")
    _booleans(value, ("junit_available", "timed_out"), label)
    _objects(value.get("cases", []), label + ".cases")
    if value.get("generated") is not None and not isinstance(value["generated"], dict):
        raise SavedReportError(f"{label}.generated must be an object or null")
    names = value.get("generated_files", [])
    if not isinstance(names, list) or any(not isinstance(name, str) for name in names):
        raise SavedReportError(f"{label}.generated_files must be an array of strings")


def _report(data: bytes) -> dict:
    try:
        report = json.loads(data.decode("utf-8"), object_pairs_hook=_unique_object,
                            parse_constant=_reject_constant, parse_float=_finite_float)
    except (UnicodeError, ValueError, RecursionError) as exc:
        raise SavedReportError(f"cannot read saved report as UTF-8 JSON: {exc}") from exc
    if not isinstance(report, dict) or report.get("schema") is not None:
        raise SavedReportError("expected an unversioned TestPilot generation report")
    for name in ("status", "patch"):
        if not isinstance(report.get(name), str):
            raise SavedReportError(f"report.{name} must be text")
    _files(report.get("test_files"), "report.test_files")
    _objects(report.get("changed_functions"), "report.changed_functions")
    rounds = _objects(report.get("rounds"), "report.rounds")
    ledger = report.get("ledger")
    if not isinstance(ledger, dict):
        raise SavedReportError("report.ledger must be an object")
    _booleans(ledger, ("tokens_estimated", "cost_is_complete"), "report.ledger")
    for entry in _objects(ledger.get("entries"), "report.ledger.entries"):
        _booleans(entry, ("estimated",), "ledger entry")
    _run_layout(report.get("final"), "report.final")
    for record in rounds:
        if "contents" in record:
            _files(record["contents"], "round.contents")
        _run_layout(record.get("result"), "round.result")
    for name in ("coverage", "pytest_selection"):
        if report.get(name) is not None and not isinstance(report[name], dict):
            raise SavedReportError(f"report.{name} must be an object or null")
    return report


def _new_output(data: bytes, destination: Path) -> str | None:
    descriptor, temporary = tempfile.mkstemp(prefix=".testpilot-review-", dir=destination.parent)
    published = False
    warning = None
    try:
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        # A complete file appears only if this final name is still unoccupied.
        os.link(temporary, destination)
        published = True
    finally:
        try:
            os.unlink(temporary)
        except OSError as exc:
            if not published:
                raise SavedReportError(f"review was not published; cannot remove temporary file {temporary}: {exc}") from exc
            warning = f"review was published; cannot remove temporary file {temporary}: {exc}"
    return warning


def reopen_report(report_path: str | Path, patch_path: str | Path,
                  output_path: str | Path) -> dict:
    """Create a new passive review of exact saved bytes; never execute them."""
    destination = Path(output_path)
    if destination.exists() or destination.is_symlink():
        raise SavedReportError("output already exists; choose a new HTML file")
    report_bytes = _read_file(Path(report_path), MAX_REPORT_BYTES, "report")
    patch_bytes = _read_file(Path(patch_path), MAX_PATCH_BYTES, "patch")
    report = _report(report_bytes)
    try:
        recorded = report["patch"].encode("utf-8")
        windows = report["patch"].replace("\n", "\r\n").encode("utf-8")
    except UnicodeError as exc:
        raise SavedReportError("recorded patch is not valid UTF-8 text") from exc
    if patch_bytes == recorded:
        newline_form = "recorded UTF-8"
    elif patch_bytes == windows:
        newline_form = "native Windows newline expansion"
    else:
        raise SavedReportError("selected patch bytes do not match the report's recorded patch")
    sources = {
        "report": {"bytes": len(report_bytes), "sha256": hashlib.sha256(report_bytes).hexdigest()},
        "patch": {"bytes": len(patch_bytes), "sha256": hashlib.sha256(patch_bytes).hexdigest(),
                  "newline_form": newline_form},
    }
    try:
        page = render_html_report(report_bytes, patch_bytes)
    except (KeyError, TypeError, AttributeError, ValueError, OverflowError, RecursionError) as exc:
        raise SavedReportError(f"saved report does not have the native renderable layout: {exc}") from exc
    marker = '<main class="shell">'
    if page.count(marker) != 1:
        raise SavedReportError("native renderer does not expose the expected review container")
    note = ('<section aria-labelledby="saved-pair-heading"><h2 id="saved-pair-heading">Saved artifact review</h2>'
            '<p>This page reopens the selected historical report and matching patch. '
            'No tests or model requests ran. Recorded outcomes have not been reverified.</p>'
            '<p>Source report: ' + str(sources["report"]["bytes"]) + ' bytes · SHA-256 '
            '<code>' + sources["report"]["sha256"] + '</code></p>'
            '<p>Source patch: ' + str(sources["patch"]["bytes"]) + ' bytes · SHA-256 '
            '<code>' + sources["patch"]["sha256"] + '</code></p>'
            '<p>Patch match: ' + newline_form + '. Both embedded downloads retain the selected bytes.</p></section>')
    output = page.replace(marker, marker + note, 1).encode("utf-8")
    warning = _new_output(output, destination)
    receipt = {"schema": "testpilot.saved_review/1", "output": str(destination),
               "bytes": len(output), "sha256": hashlib.sha256(output).hexdigest(),
               "sources": sources, "recorded_status": report["status"]}
    if warning is not None:
        receipt["cleanup_warning"] = warning
    return receipt


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Reopen saved TestPilot artifacts as a new offline HTML review.")
    parser.add_argument("--report", required=True, help="saved generation report JSON")
    parser.add_argument("--patch", required=True, help="matching saved testpilot.patch")
    parser.add_argument("--out", required=True, help="new HTML file in an existing directory")
    args = parser.parse_args(argv)
    try:
        receipt = reopen_report(args.report, args.patch, args.out)
    except (OSError, SavedReportError) as exc:
        print(f"testpilot: cannot reopen saved report: {exc}", file=sys.stderr)
        return 2
    print(json.dumps(receipt, sort_keys=True), flush=True)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
